using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class ToniMorrison
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "The very serious function of racism is distraction. It keeps you from doing your work. It keeps you explaining over and over again, your reason for being.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "At some point in life the world's beauty becomes enough. You don't need to photograph, paint or even remember it. It is enough. No record of it needs to be kept and you don't need someone to share it with or tell it to. When that happens — that letting go — you let go because you can.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "If there is a book that you want to read, but it hasn't been written yet, you must be the one to write it.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "The ability of writers to imagine what is not the self, to familiarize the strange and mystify the familiar, is the test of their power.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "I remember a very important lesson that my father gave me when I was twelve or thirteen. He said, \"You know, today I welded a perfect seam and I signed my name to it.\" And I said, \"But, Daddy, no one's going to see it!\" And he said, \"Yeah, but I know it's there.\" So when I was working in kitchens, I did good work.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Everywhere, everywhere, children are the scorned people of the earth.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "They shoot the white girl first. With the rest they can take their time. No need to hurry out here. They are seventeen miles from a town which has ninety miles between it and any other. Hiding places will be plentiful in the Convent, but there is time and the day has just begun.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "We all know nations that can be identified by the flight of writers from their shores. These are regimes whose fear of unmonitored writing is justified because truth is trouble. It is trouble for the warmonger, the torturer, the corporate thief, the political hack, the corrupt justice system, and for a comose public. Unpersecuted, unjailed, unharrassed writers are trouble for the ignorant bully, the sly racist, and the predators feeding off the world’s resources. The alarm, the disquiet, writers raise is instructive because it is open and vulnerable, because if unpoliced it is threatening. Therefore the historical suppression of writers is the earliest harbinger of the steady peeling away of additional rights and liberties that will follow.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "You free. Nothing and nobody is obliged to save you but you.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "I always know the ending; that's where I start.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Like any artist with no art form, she became dangerous.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "It was a fine cry — loud and long — but it had no bottom and it had no top, just circles and circles of sorrow.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "No one can blame the conqueror for writing history the way he sees it, and certainly not for digesting human events and discovering their patterns according to his own point of view. But it must be admitted … that conventional history supports and complements a very grave and almost pristine ignorance.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "It would seem that to continue to see race of people, any race of people as one single personality is an ignorance of gothic proportions, an ignorance so vast, so public, and perception so blind and so blunted, imagination so bleak that no nuance, no subtlety, no difference among them can be ascertained.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "It’s important, therefore, to know who the real enemy is, and to know the function, the very serious function of racism, which is distraction. It keeps you from doing your work. It keeps you explaining over and over again, your reason for being.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "To the artist one can only say, not to be confused, — not to be confused. You don’t waste your energy fighting the fever; you must only fight the disease. And the disease is not racism. It is greed and the struggle for power.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Where the mind dwells on changing the minds of racists is a very dank place. Where the spirit hangs limp in silk cords of the racial apologists who want soft and delicate treatment for the poor victims is a very dim place. And where the will that you allow to be eroded day by day, day by day, by consistent assaults from racists, then the will just settles into a little tiny heap of sand, and you just have a second-rate existence, jammed with second-hand ideas.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Racial ignorance is a prison from which there is no escape because there’re no doors. And there are old, old men, and old, old women running institutions, governments, homes all over the world who need to believe in their racism and need to have the victims of racism concentrate all their creative abilities on them.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "They are the petulant ones who call themselves proud, and they are the disdainful ones who call themselves fastidious, and they are the mean-spirited ones who call themselves just. They thrive on the failures of those unlike them; they are the ones who measure their wealth by the desperation of the poor. They are the ones who know personal success only when they can identify deficiencies in other racial and ethnic groups. They are in prisons of their own construction: and their ignorance and their stunted emotional growth consistently boggle the mind.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "We are the moral inhabitants of the globe. And to deny it is to lie in prison. Oh yes, there’s cruelty, and cruelty, because it destroys the perpetuator as well as the victim, is a very mysterious thing. But if you look at the world as one long brutal game between “us” and “them,” then you bump into another mystery.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "And unless all races and all ages of man have been totally deluded, there seems to be such a thing as grace, such a thing as beauty, such a thing as harmony — all of which are wholly free, and available to us.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "What difference do it make if the thing you scared of is real or not?", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Wanna fly, you got to give up the shit that weighs you down.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "If you surrendered to the air, you could ride it.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "124 was spiteful. Full of a baby's venom.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Anything dead coming back to life hurts.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "More it hurt more better it is. Can't nothing heal without pain, you know.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Bit by bit, at 124 and in the Clearing, along with others, she had claimed herself. Freeing yourself was one thing; claiming ownership of that freed self was another.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Except for an occasional request for color she said practically nothing — until the afternoon of the last day of her life when she got out of bed, skipped slowly to the door of the keeping room and announced to Sethe and Denver the lesson she had learned from her sixty years a slave and ten years free: that there was no bad luck in the world but whitepeople.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "They killed the flirt whom folks called Life for leading them on. Making them think the next sunrise would be worth it; that another stroke of time would do it at last. Only when she was dead would they be safe.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "This is worse than when Paul D came to 124 and she cried helplessly into the stove. This is worse. Then it was for herself. Now she is crying because she has no self . . . She doesn't move to open the door because there is no world out there.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "He knew what she was thinking and even though she was wrong — he was not leaving her, wouldn't ever — the thing he had in mind to tell her was going to be worse. So, when he saw the diminished expectation in her eyes, the melancholy without blame, he could not say it. He could not say to this woman who did not squint in the wind, \"I am not a man.\"", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Resolve, he thought. That was all it took, and no motherless gal was going to break it up. No lazy, stray pup of a woman could turn him around, make him doubt himself, wonder, plead or confess.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Unless carefree, motherlove was a killer.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "What for? What does a sixty-odd-year-old slavewoman who walks like a three-legged dog need freedom for? And when she stepped foot on free ground she could not believe that Halle knew what she didn’t; that Halle, who had never drawn one free breath, knew that there was nothing like it in this world. It scared her.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Something's the matter. What's the matter? What's the matter? She asked herself. She didn't know what she looked like and was not curious. But suddenly she saw her hands and thought with a clarity as simple as it was dazzling, \"These hands belong to me. These ''my'' hands.\"", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Even then care was taken, because the quietest ones, the ones you pulled from a press, a hayloft, or, that once, from a chimney, would go along nicely for two or three seconds. Caught red-handed, so to speak, they would seem to recognize the futility of outsmarting a whiteman and the hopelessness of outrunning a rifle.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "I did it. I got us all out. Without Halle too. Up till then it was the only thing I ever did on my own. Decided. And it came off right, like it was suppose to. We was here. Each and every one of my babies and me too. I birthed them and I got em out and it wasn't no accident. I had help, of course, lots of that, but still it was me doing it; me saying ''Go on,'' and ''Now''.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "He knew exactly what she meant: to get to a place where you could love anything you choose — not to need permission for desire — well now, ''that'' was freedom.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Born Joshua, he renamed himself when he handed over his wife to his master’s son. Handed her over in the sense that he did not kill anybody, thereby himself, because his wife demanded he stay alive.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Clever, but schoolteacher beat him anyway to show him that definitions belonged to the definers — not the defined.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Whitepeople believed that whatever the manners, under every dark skin was a jungle. Swift unnavigable waters, swinging screaming baboons, sleeping snakes, red gums ready for their sweet white blood. In a way, he thought, they were right.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "The screaming baboon lived under their own white skin; the red gums were their own.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "All the time, I'm afraid the thing that happened that made it all right for my mother to kill my sister could happen again. I don't know what it is, I don't know who it is, but maybe there is something else terrible enough to make her do it again.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "I am Beloved and she is mine. I see her take flowers away from leaves she puts them in a round basket the leaves are not for her she fills the basket she opens the grass I would help her but the clouds are in the way how can I say things that are pictures I am not separate from her there is no place where I stop her face is my own and I want to be there in the place where her face is and to be looking at it too a hot thing.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Beloved, you are my sister, you are my daughter, you are my face; you are me.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Garner called and announced them men — but only on Sweet Home, and by his leave. Was he naming what he saw or creating what he did not?", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "\"Tell me something, Stamp.\" Paul D's eyes were rheumy. \"Tell me this one thing. How much is a nigger supposed to take? Tell me. How much?\" \"All he can,\" said Stamp Paid. \"All he can.\"", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Maybe they were sorry for her. Or for Sethe. Maybe they were sorry for the years of their own disdain. Maybe they were simply nice people who could hold meanness toward each other for just so long and when trouble rode bareback among them, quickly, easily they did what they do to trip him up.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Anybody white could take your whole self for anything that came to mind. Not just work, kill, or maim you, but dirty you. Dirty you so bad you couldn't like yourself anymore.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "What's fair ain't necessarily true.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Human life is holy, all of it.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Everybody knew what she was called, but nobody anywhere knew her name. Disremembered and unaccounted for, she cannot be lost because no one is looking for her, and even if they were, how can they call her if they don't know her name? Although she has claim, she is not claimed.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "This is not a story to pass on.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "How soon country people forget. When they fall in love with a city it is forever, and it is like forever. As though there never was a time when they didn't love it.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Even if the room they rented was smaller than the heifer’s stall and darker than a morning privy, they stayed to look at their number, hear themselves in an audience, feel themselves moving down the street among hundreds of others who moved the way they did, and who, when they spoke, regardless of the accent, treated language like the same intricate, malleable toy designed for their play.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Born lost. Take over the world and still lost.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "The screams of a hurt woman were indistinguishable from everyday traffic.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Which was what love was: unmotivated respect.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Love is divine only and difficult always. If you think it is easy you are a fool. If you think it is natural you are blind. It is a learned application without reason or motive except that it is God.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Nothing like other folks' sin for distraction.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Now they will rest before shouldering the endless work they were created to do down here in paradise.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Once upon a time there was an old woman. Blind. Wise. In the version I know the woman is the daughter of slaves, black, American, and lives alone in a small house outside of town.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Finally she speaks and her voice is soft but stern. \"I don't know\", she says. \"I don't know whether the bird you are holding is dead or alive, but what I do know is that it is in your hands. It is in your hands.\"", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "A dead language is not only one no longer spoken or written, it is unyielding language content to admire its own paralysis. Like statist language, censored and censoring.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "Oppressive language does more than represent violence; it is violence; does more than represent the limits of knowledge; it limits knowledge.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "There is and will be rousing language to keep citizens armed and arming; slaughtered and slaughtering in the malls, courthouses, post offices, playgrounds, bedrooms and boulevards; stirring, memorializing language to mask the pity and waste of needless death. There will be more diplomatic language to countenance rape, torture, assassination.", Author = "Toni Morrison" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Toni_Morrison", Text = "The vitality of language lies in its ability to limn the actual, imagined and possible lives of its speakers, readers, writers. Although its poise is sometimes in displacing experience it is not a substitute for it.", Author = "Toni Morrison" },
        };
    }
}